-- A&A Urban Store: perfiles, productos y Supabase Storage para imágenes.
-- Ejecuta en Supabase > SQL Editor. El bucket product-images es público para mostrar fotos.
begin;
create table if not exists public.user_profiles (
 user_id uuid primary key references auth.users(id) on delete cascade,
 display_name text not null default '',
 role text not null default 'catalog' check(role in ('owner','inventory','catalog','sales')),
 permissions text[] not null default '{}',
 created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table if not exists public.products (
 id bigint generated by default as identity primary key,
 name text not null, brand text not null, category text not null default 'Urban', badge text not null default '', price numeric(10,2) not null default 0 check(price>=0),
 image_url text not null, gallery jsonb not null default '[]'::jsonb,
 sizes jsonb not null default '[]'::jsonb, stock jsonb not null default '{}'::jsonb,
 description text not null default '', active boolean not null default true,
 created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
alter table public.products add column if not exists gallery jsonb not null default '[]'::jsonb;
alter table public.products add column if not exists category text not null default 'Urban';
alter table public.products add column if not exists badge text not null default '';
-- El campo Talla del esquema funcional se almacena como sizes (JSONB) para que el catálogo existente lo lea sin cambios.
alter table public.products add column if not exists updated_at timestamptz not null default now();
alter table public.user_profiles add column if not exists permissions text[] not null default '{}';
alter table public.user_profiles add column if not exists updated_at timestamptz not null default now();
create or replace function public.set_updated_at() returns trigger language plpgsql set search_path=public as $$ begin new.updated_at=now(); return new; end; $$;
drop trigger if exists products_set_updated_at on public.products;
create trigger products_set_updated_at before update on public.products for each row execute function public.set_updated_at();
drop trigger if exists user_profiles_set_updated_at on public.user_profiles;
create trigger user_profiles_set_updated_at before update on public.user_profiles for each row execute function public.set_updated_at();
create or replace function public.handle_new_auth_user() returns trigger language plpgsql security definer set search_path=public as $$ begin
 insert into public.user_profiles(user_id,display_name,role,permissions) values(new.id,coalesce(new.raw_user_meta_data->>'display_name',''),'catalog','{}'::text[]) on conflict(user_id) do nothing; return new; end; $$;
drop trigger if exists on_auth_user_created_profile on auth.users;
create trigger on_auth_user_created_profile after insert on auth.users for each row execute function public.handle_new_auth_user();
create or replace function public.current_role() returns text language sql stable security definer set search_path=public as $$ select role from public.user_profiles where user_id=(select auth.uid()) limit 1; $$;
create or replace function public.has_permission(permission_name text) returns boolean language sql stable security definer set search_path=public as $$ select coalesce((select role='owner' or permission_name=any(permissions) from public.user_profiles where user_id=(select auth.uid()) limit 1),false); $$;
alter table public.user_profiles enable row level security;
alter table public.products enable row level security;
drop policy if exists "read own profile" on public.user_profiles;
drop policy if exists "owner reads all profiles" on public.user_profiles;
drop policy if exists "owner updates other profiles" on public.user_profiles;
drop policy if exists "owner updates profiles" on public.user_profiles;
drop policy if exists "public reads active products" on public.products;
drop policy if exists "staff reads all products" on public.products;
drop policy if exists "create authorized products" on public.products;
drop policy if exists "update authorized products" on public.products;
drop policy if exists "delete authorized products" on public.products;
create policy "read own profile" on public.user_profiles for select to authenticated using(user_id=(select auth.uid()));
create policy "owner reads all profiles" on public.user_profiles for select to authenticated using(public.current_role()='owner');
create policy "owner updates other profiles" on public.user_profiles for update to authenticated using(public.current_role()='owner' and user_id<>(select auth.uid())) with check(public.current_role()='owner' and user_id<>(select auth.uid()));
create policy "public reads active products" on public.products for select to anon,authenticated using(active=true);
create policy "staff reads all products" on public.products for select to authenticated using(public.current_role()='owner' or public.has_permission('products_create') or public.has_permission('products_update') or public.has_permission('products_delete'));
create policy "create authorized products" on public.products for insert to authenticated with check(public.has_permission('products_create'));
create policy "update authorized products" on public.products for update to authenticated using(public.has_permission('products_update')) with check(public.has_permission('products_update'));
create policy "delete authorized products" on public.products for delete to authenticated using(public.has_permission('products_delete'));
grant select on public.products to anon,authenticated;
grant insert,update,delete on public.products to authenticated;
grant select,update on public.user_profiles to authenticated;
grant usage,select on sequence public.products_id_seq to authenticated;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('product-images','product-images',true,8388608,array['image/jpeg','image/png','image/webp','image/gif','image/avif']) on conflict(id) do update set public=excluded.public,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;
drop policy if exists "Public can view product images" on storage.objects;
drop policy if exists "Authorized staff upload product images" on storage.objects;
drop policy if exists "Authorized staff delete product images" on storage.objects;
create policy "Public can view product images" on storage.objects for select to anon,authenticated using(bucket_id='product-images');
create policy "Authorized staff upload product images" on storage.objects for insert to authenticated with check(bucket_id='product-images' and (public.has_permission('products_create') or public.has_permission('products_update')));
create policy "Authorized staff delete product images" on storage.objects for delete to authenticated using(bucket_id='product-images' and (public.has_permission('products_update') or public.has_permission('products_delete')));
commit;
-- Después crea el usuario en Authentication > Users, copia su UUID y ejecuta:
-- update public.user_profiles set display_name='Propietario A&A', role='owner', permissions=array['products_create','products_update','products_delete','stock_manage'] where user_id='UUID_REAL';
-- Desactiva el registro público en Authentication > Settings si solo el propietario debe crear cuentas.
